from pypdf import PdfReader
import re
for n in [1,2,3,4,5]:
 t='\n'.join(p.extract_text() for p in PdfReader(f'studies/papers/paper_{n}.pdf').pages)
 print('\nPAPER',n)
 patterns= r'24\s*(?:h|hour)|microarray|4-hydroxy|4-OH|RNA.seq'
 matches=list(re.finditer(patterns,t,re.I))
 for m in matches:
  if n in [2,3] or ('24' in m.group()):print(t[max(0,m.start()-300):m.end()+450].replace('\n',' '))

